package org.beckenburg;

import java.util.ArrayList;
import java.util.List;

/**
 * Host-owned physical camera stations. The receiver renders the actual game
 * scene from this replicated camera pose; no guessed ghost, fake clip, or
 * spectral-evidence verdict is generated by the camera.
 */
public final class LanVideoCameras {
    public record Camera(int owner,int room,double x,double y,double z,int heading,
                         EquipmentTiers.Tier tier) {
        public Camera(int owner,int room,double x,double z,int heading,EquipmentTiers.Tier tier){this(owner,room,x,0,z,heading,tier);}
        public Camera {
            if(owner<0||owner>=6||room<0||room>=HouseMap.ROOM_COUNT
                ||!Double.isFinite(x)||!Double.isFinite(y)||!Double.isFinite(z)
                ||heading<0||heading>=360||tier==null)
                throw new IllegalArgumentException("invalid camera station");
        }
        public String frame(){
            return "CAMERA|PLACE|"+owner+"|"+room+"|"+
                Math.round(x*1000)+"|"+Math.round(y*1000)+"|"+Math.round(z*1000)+"|"+heading+"|"+tier;
        }
    }
    private final Camera[] stations=new Camera[6];
    public Camera at(int owner) {
        if(owner<0||owner>=6)throw new IllegalArgumentException("hunter seat");
        return stations[owner];
    }
    public Camera placeOrRetrieve(int owner,LanWorld.Body body,EquipmentTiers.Tier tier) {
        return placeOrRetrieve(owner,body,tier,null);
    }
    public Camera placeOrRetrieve(int owner,LanWorld.Body body,EquipmentTiers.Tier tier,
                                  VanTripods.Stand mount) {
        if(body==null||tier==null||body.room()<0||body.room()>=HouseMap.ROOM_COUNT)
            throw new IllegalArgumentException("camera needs physical location");
        Camera old=at(owner);
        if(old!=null){
            if(old.room()!=body.room()||Math.abs(old.y()-body.y())>.75||Math.hypot(old.x()-body.x(),old.z()-body.z())>1.6)
                throw new IllegalArgumentException("retrieve camera beside the device");
            stations[owner]=null;
            return null;
        }
        // The stand fixes the camera position. The lens elevation is reflected
        // in the actual camera pose used by the remote van receiver.
        if(mount!=null&&(mount.room()!=body.room()
                ||Math.abs(mount.y()-body.y())>.5
                ||Math.hypot(mount.x()-body.x(),mount.z()-body.z())>.9))
            throw new IllegalArgumentException("tripod mount out of reach");
        Camera placed=mount==null
            ?new Camera(owner,body.room(),body.x(),body.y(),body.z(),body.heading(),tier)
            :new Camera(owner,mount.room(),mount.x(),mount.y()+.45,
                mount.z(),body.heading(),tier);
        stations[owner]=placed;
        return placed;
    }
    public List<Camera> all(){
        List<Camera> out=new ArrayList<>();
        for(Camera station:stations)if(station!=null)out.add(station);
        return List.copyOf(out);
    }
}
